import csv
import sys

def filter_csv(input_file, output_file, column_name, condition_value, operator='=='):
    """
    Filter CSV rows based on a condition.

    Args:
        input_file: Path to input CSV file
        output_file: Path to output CSV file
        column_name: Name of column to filter on
        condition_value: Value to compare against
        operator: Comparison operator ('==', '!=', '>', '<', '>=', '<=', 'contains')
    """
    try:
        with open(input_file, 'r', newline='', encoding='utf-8') as infile:
            reader = csv.DictReader(infile)

            if reader.fieldnames is None:
                print("Error: CSV file is empty or invalid")
                return

            if column_name not in reader.fieldnames:
                print(f"Error: Column '{column_name}' not found in CSV")
                return

            filtered_rows = []

            for row in reader:
                cell_value = row[column_name]

                if operator == '==':
                    if cell_value == condition_value:
                        filtered_rows.append(row)
                elif operator == '!=':
                    if cell_value != condition_value:
                        filtered_rows.append(row)
                elif operator == '>':
                    try:
                        if float(cell_value) > float(condition_value):
                            filtered_rows.append(row)
                    except ValueError:
                        pass
                elif operator == '<':
                    try:
                        if float(cell_value) < float(condition_value):
                            filtered_rows.append(row)
                    except ValueError:
                        pass
                elif operator == '>=':
                    try:
                        if float(cell_value) >= float(condition_value):
                            filtered_rows.append(row)
                    except ValueError:
                        pass
                elif operator == '<=':
                    try:
                        if float(cell_value) <= float(condition_value):
                            filtered_rows.append(row)
                    except ValueError:
                        pass
                elif operator == 'contains':
                    if condition_value.lower() in cell_value.lower():
                        filtered_rows.append(row)

            with open(output_file, 'w', newline='', encoding='utf-8') as outfile:
                if filtered_rows:
                    writer = csv.DictWriter(outfile, fieldnames=reader.fieldnames)
                    writer.writeheader()
                    writer.writerows(filtered_rows)
                    print(f"Successfully filtered CSV. {len(filtered_rows)} rows written to {output_file}")
                else:
                    print("No rows matched the filter condition")

    except FileNotFoundError:
        print(f"Error: File '{input_file}' not found")
    except Exception as e:
        print(f"Error processing CSV: {e}")


if __name__ == "__main__":
    if len(sys.argv) < 5:
        filter_csv('input.csv', 'output.csv', 'name', 'John', '==')
    else:
        input_file = sys.argv[1]
        output_file = sys.argv[2]
        column = sys.argv[3]
        value = sys.argv[4]
        operator = sys.argv[5] if len(sys.argv) > 5 else '=='
        filter_csv(input_file, output_file, column, value, operator)

using System;
using System.Collections.Generic;
using System.Linq;

public class ShoppingCart
{
    private List<CartItem> items;

    public ShoppingCart()
    {
        items = new List<CartItem>();
    }

    public void AddItem(string productName, decimal price, int quantity = 1)
    {
        var existingItem = items.FirstOrDefault(i => i.ProductName == productName);

        if (existingItem != null)
        {
            existingItem.Quantity += quantity;
        }
        else
        {
            items.Add(new CartItem
            {
                ProductName = productName,
                Price = price,
                Quantity = quantity
            });
        }
    }

    public bool RemoveItem(string productName)
    {
        var item = items.FirstOrDefault(i => i.ProductName == productName);
        if (item != null)
        {
            items.Remove(item);
            return true;
        }
        return false;
    }

    public bool RemoveItemQuantity(string productName, int quantity)
    {
        var item = items.FirstOrDefault(i => i.ProductName == productName);
        if (item != null)
        {
            if (item.Quantity <= quantity)
            {
                items.Remove(item);
            }
            else
            {
                item.Quantity -= quantity;
            }
            return true;
        }
        return false;
    }

    public List<CartItem> GetItems()
    {
        return new List<CartItem>(items);
    }

    public decimal GetTotal()
    {
        return items.Sum(i => i.Price * i.Quantity);
    }

    public int GetItemCount()
    {
        return items.Count;
    }

    public void Clear()
    {
        items.Clear();
    }
}

public class CartItem
{
    public string ProductName { get; set; }
    public decimal Price { get; set; }
    public int Quantity { get; set; }

    public decimal GetSubtotal()
    {
        return Price * Quantity;
    }
}

class Program
{
    static void Main()
    {
        var cart = new ShoppingCart();

        cart.AddItem("Laptop", 999.99m, 1);
        cart.AddItem("Mouse", 29.99m, 2);
        cart.AddItem("Keyboard", 79.99m, 1);

        Console.WriteLine("Items in cart: " + cart.GetItemCount());
        Console.WriteLine("Total: $" + cart.GetTotal());
        Console.WriteLine();

        foreach (var item in cart.GetItems())
        {
            Console.WriteLine($"{item.ProductName}: ${item.Price} x {item.Quantity} = ${item.GetSubtotal()}");
        }

        Console.WriteLine();
        cart.RemoveItem("Mouse");
        Console.WriteLine("After removing Mouse:");
        Console.WriteLine("Items in cart: " + cart.GetItemCount());
        Console.WriteLine("Total: $" + cart.GetTotal());
    }
}

