from functools import wraps
import inspect


class TypeCheckMeta(type):
    def __new__(mcs, name, bases, namespace):
        # Process class attributes
        hints = namespace.get('__annotations__', {})

        # Wrap methods with type checking
        for attr_name, attr_value in namespace.items():
            if callable(attr_value) and not attr_name.startswith('_'):
                namespace[attr_name] = mcs._wrap_method(attr_value)

        # Store type hints on the class
        cls = super().__new__(mcs, name, bases, namespace)
        cls._type_hints = hints

        return cls

    @staticmethod
    def _wrap_method(method: Callable) -> Callable:
        @wraps(method)
        def wrapper(*args, **kwargs):
            try:
                hints = get_type_hints(method)
            except Exception:
                hints = {}

            sig = inspect.signature(method)
            params = sig.parameters

            # Get all arguments bound to parameters
            bound_args = sig.bind(*args, **kwargs)
            bound_args.apply_defaults()

            # Type check each parameter
            for param_name, param_value in bound_args.arguments.items():
                if param_name in hints and param_name != 'return':
                    expected_type = hints[param_name]

                    if not mcs._check_type(param_value, expected_type):
                        raise TypeError(
                            f"Parameter '{param_name}' expected type "
                            f"{expected_type}, got {type(param_value).__name__}"
                        )

            # Call the actual method
            result = method(*args, **kwargs)

            # Type check return value
            if 'return' in hints and result is not None:
                expected_return = hints['return']
                if not mcs._check_type(result, expected_return):
                    raise TypeError(
                        f"Return value expected type {expected_return}, "
                        f"got {type(result).__name__}"
                    )

            return result

        return wrapper

    @staticmethod
    def _check_type(value: Any, expected_type: Any) -> bool:
        # Handle Union types
        if hasattr(expected_type, '__origin__'):
            import typing
            if expected_type.__origin__ is typing.Union:
                return any(
                    isinstance(value, t) if isinstance(t, type) else True
                    for t in expected_type.__args__
                )
            elif expected_type.__origin__ in (list, tuple, dict, set):
                return isinstance(value, expected_type.__origin__)

        # Handle basic types
        if isinstance(expected_type, type):
            return isinstance(value, expected_type)

        # For complex types, allow if not explicitly defined
        return True

    def __setattr__(cls, name, value):
        hints = getattr(cls, '_type_hints', {})

        if name in hints:
            expected_type = hints[name]
            if not isinstance(value, expected_type):
                raise TypeError(
                    f"Attribute '{name}' expected type {expected_type}, "
                    f"got {type(value).__name__}"
                )

        super().__setattr__(name, value)


class TypeCheckedClass(metaclass=TypeCheckMeta):
    """Base class for classes with type checking enforcement"""
    pass


