    public class UserRegisteredEventArgs : EventArgs
    {
        public string UserId { get; set; }
        public string Username { get; set; }
        public DateTime RegisteredAt { get; set; }
    }

    public class OrderPlacedEventArgs : EventArgs
    {
        public string OrderId { get; set; }
        public string UserId { get; set; }
        public decimal Amount { get; set; }
        public DateTime OrderedAt { get; set; }
    }

    public class PaymentProcessedEventArgs : EventArgs
    {
        public string PaymentId { get; set; }
        public string OrderId { get; set; }
        public decimal Amount { get; set; }
        public bool IsSuccessful { get; set; }
        public DateTime ProcessedAt { get; set; }
    }

    public class NotificationSentEventArgs : EventArgs
    {
        public string NotificationId { get; set; }
        public string Recipient { get; set; }
        public string Message { get; set; }
        public DateTime SentAt { get; set; }
    }

    // Custom Delegates
    public delegate void UserRegisteredEventHandler(object sender, UserRegisteredEventArgs e);
    public delegate void OrderPlacedEventHandler(object sender, OrderPlacedEventArgs e);
    public delegate void PaymentProcessedEventHandler(object sender, PaymentProcessedEventArgs e);
    public delegate void NotificationSentEventHandler(object sender, NotificationSentEventArgs e);

    // Event Publisher - User Service
    public class UserService
    {
        public event UserRegisteredEventHandler UserRegistered;

        public void RegisterUser(string userId, string username)
        {
            Console.WriteLine($"[UserService] Registering user: {username}");

            var args = new UserRegisteredEventArgs
            {
                UserId = userId,
                Username = username,
                RegisteredAt = DateTime.Now
            };

            OnUserRegistered(args);
        }

        protected virtual void OnUserRegistered(UserRegisteredEventArgs e)
        {
            UserRegistered?.Invoke(this, e);
        }
    }

    // Event Publisher - Order Service
    public class OrderService
    {
        public event OrderPlacedEventHandler OrderPlaced;
        private List<string> orders = new List<string>();

        public void PlaceOrder(string orderId, string userId, decimal amount)
        {
            Console.WriteLine($"[OrderService] Placing order: {orderId} for user: {userId}");
            orders.Add(orderId);

            var args = new OrderPlacedEventArgs
            {
                OrderId = orderId,
                UserId = userId,
                Amount = amount,
                OrderedAt = DateTime.Now
            };

            OnOrderPlaced(args);
        }

        protected virtual void OnOrderPlaced(OrderPlacedEventArgs e)
        {
            OrderPlaced?.Invoke(this, e);
        }

        public List<string> GetOrders() => new List<string>(orders);
    }

