        public void ProcessPayment(string paymentId, string orderId, decimal amount)
        {
            Console.WriteLine($"[PaymentService] Processing payment: {paymentId} for order: {orderId}");

            bool isSuccessful = new Random().Next(0, 100) > 10;
            processedPayments.Add(paymentId);

            var args = new PaymentProcessedEventArgs
            {
                PaymentId = paymentId,
                OrderId = orderId,
                Amount = amount,
                IsSuccessful = isSuccessful,
                ProcessedAt = DateTime.Now
            };

            OnPaymentProcessed(args);
        }

        protected virtual void OnPaymentProcess
